export function ensureStyles() {
  document.getElementById(STYLE_ID)?.remove()
  const style = document.createElement('style')
  style.id = STYLE_ID
  style.dataset.plugin = STYLE_OWNER
  style.textContent = STYLE_TEXT
  document.head.append(style)
  return () => style.remove()
}
